      !terminal.finish || ["tool-calls", "unknown", "error"].includes(terminal.finish) && !terminal.structured) return
    const unsettled = [...s.guides.values()].some(g => !g.saved || g.dirty || g.saved !== g.prepared && g.saved !== g.compacted)
